def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # We've reached the end of the line
        if i == n:
            fields.append("")
            break

        # Check if this field is quoted
        if line[i] == '"':
            # Parse quoted field
            i += 1
            field = ""
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == n:
                            fields.append(field)
                            return fields
                        elif line[i] == ',':
                            fields.append(field)
                            i += 1
                            # If we're at the end after comma, the next field is empty
                            if i == n:
                                fields.append("")
                                return fields
                            break
                        else:
                            # Invalid: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # We reached end of line without finding closing quote
                return None
        else:
            # Parse unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i == n:
                # End of line
                break
            else:
                # We're at a comma
                i += 1
                # If we're at the end after comma, the next field is empty
                if i == n:
                    fields.append("")
                    break

    return fields

